            referrer_discount_bps,
            referee_discount_bps,
            referrer_deposit_usd_threshold,
        );

    emit(ReferralUpdatedEvent {
        app: object::id(app),

        referrer_discount_bps,
        referee_discount_bps,
        referrer_deposit_usd_threshold,

        sender: ctx.sender(),
        timestamp_ms: clock::timestamp_ms(clock),
    });

}

